// --- widget.h --- (Interface)
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Declaration is crucial

    // Move operations must also be declared
    Widget(Widget&& rhs) noexcept;
    Widget& operator=(Widget&& rhs) noexcept;

    // Copy operations would be handled similarly if supported
    Widget(const Widget& rhs);
    Widget& operator=(const Widget& rhs);

private:
    struct Impl; // Forward-declared implementation type
    std::unique_ptr<Impl> pImpl; // Pointer to implementation
};


// --- widget.cpp --- (Implementation)
#include "widget.h"
#include <string>
#include <vector>

// Full definition of the implementation type
struct Widget::Impl {
    std::string name;
    std::vector<double> data;
};

// Destructor definition where Impl is a complete type
Widget::~Widget() = default;

// Move operations definitions where Impl is a complete type
Widget::Widget(Widget&& rhs) noexcept = default;
Widget& Widget::operator=(Widget&& rhs) noexcept = default;

// Constructor and other member functions defined here
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}

// Deep copy implementations if copy is supported
Widget::Widget(const Widget& rhs) 
    : pImpl(std::make_unique<Impl>(*rhs.pImpl)) {}
Widget& Widget::operator=(const Widget& rhs) {
    if (this != &rhs) {
        *pImpl = *rhs.pImpl;
    }
    return *this;
}
